/// Whether every literal variant of the union is subsumed by a primitive
/// variant of the same base type that is also present in the union
/// (e.g. `"a" | string`, `"a" | "b" | string`, `1 | 2 | number`, `1n | bigint`).
/// Such a union collapses to a single primitive, so there is nothing to narrow.
fn union_literals_all_absorbed(ty: &Type) -> bool {
    let variants: Vec<Type> = ty.flattened_union_variants().collect();
    let has_string = variants.iter().any(|v| matches!(&**v, TypeData::String));
    let has_number = variants.iter().any(|v| matches!(&**v, TypeData::Number));
    let has_boolean = variants.iter().any(|v| matches!(&**v, TypeData::Boolean));
    let has_bigint = variants.iter().any(|v| matches!(&**v, TypeData::BigInt));

    let mut has_literal = false;
    for variant in &variants {
        if let TypeData::Literal(lit) = &**variant {
            has_literal = true;
            let absorbed = match lit.as_ref() {
                Literal::String(_) | Literal::Template(_) => has_string,
                Literal::Number(_) => has_number,
                Literal::Boolean(_) => has_boolean,
                Literal::BigInt(_) => has_bigint,
                _ => false,
            };
            if !absorbed {
                return false;
            }
        }
    }

    has_literal
}

