47	    fn new(mut variants: Vec<TypeReference>, resolver: &'a dyn TypeResolver) -> Self {
48	        // Reverse in-place so we can efficiently pop them later.
49	        variants.reverse();
50	
51	        Self {
52	            resolver,
53	            unions: vec![variants],
54	            previous_references: Default::default(),
55	        }
56	    }
