68	    type Item = TypeReference;
69	
70	    fn next(&mut self) -> Option<Self::Item> {
71	        let mut union = self.unions.last_mut()?;
72	        loop {
73	            let reference = match union.pop() {
74	                Some(reference) => reference,
75	                None => {
76	                    self.unions.pop();
77	                    union = self.unions.last_mut()?;
78	                    continue;
79	                }
80	            };
81	
82	            if self.previous_references.insert(reference.clone()) {
83	                if let Some(ty) = self.resolver.resolve_and_get(&reference)
84	                    && ty.is_union()
85	                    && let TypeData::Union(nested) = ty.to_data()
